// Gas sensor — an analogue reading and a comparator threshold.
//
// AOUT is the sensor's heater/chemiresistor divider: more gas, higher voltage.
// DOUT is the module's comparator, high once the reading passes half scale.
// Move the Gas slider in the properties strip and watch both values.

void setup() {
  Serial.begin(9600);
  pinMode(2, INPUT);
}

void loop() {
  Serial.print("gas ");
  Serial.print(analogRead(A0));
  Serial.print("/1023  DOUT ");
  Serial.println(digitalRead(2) == HIGH ? "high" : "low");
  delay(200);
}
